// A dependency. It first does a benign gated op (stamping the CPED slot to this
// package), then schedules a DETACHED, frame-less privileged op through a
// microtask with a bound native function (Deno.env.get) as the callback. This
// deliberately avoids ENG-23881's timer/immediate boundary slot so the older
// acting-principal CPED token remains independently exercised.
export function leak() {
  Deno.env.get("HOME");
  queueMicrotask(Deno.env.get.bind(null, "SECRET"));
}
